window.AUTH=window.AUTH||{};window.AUTH["16-1435"]={"d":"16-1435","id":"2017/16-1435","n":"Minnesota Voters Alliance v. Mansky","briefs":[{"k":"petitioner","label":"Brief of petitioners Minnesota Voters Alliance, et al.","date":"2018-01-05","url":"https://www.supremecourt.gov/DocketPDF/16/16-1435/26848/20180105123954331_EFILE%20opening%20brief.pdf","side":"pet","n":80},{"k":"respondent","label":"Brief of respondents Joe Mansky, et al.","date":"2018-02-05","url":"https://www.supremecourt.gov/DocketPDF/16/16-1435/34363/20180205120358107_16-1435bs%20-%20Brief%20of%20Respondents.pdf","side":"res","n":72},{"k":"reply","label":"Reply of petitioners Minnesota Voters Alliance, et al.","date":"2018-02-19","url":"https://www.supremecourt.gov/DocketPDF/16/16-1435/35851/20180220114525208_EFILE%2016-1435%20REPLY%20BRIEF.pdf","side":"pet","n":53}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Arizona Free Enterprise Club’s Freedom Club PAC v. Bennett","cite":"564 U.S. 721","y":2011,"id":"2010/10-238","sc":1,"sum":"The Court held that the Arizona campaign finance law linking public financing for candidates to the amount spent by their opponents violated the First Amendment's protection of political speech.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Ashcroft v. Free Speech Coalition","cite":"535 U.S. 234","y":2002,"id":"2001/00-795","sc":1,"sum":"The Court held that the two prohibitions described above are overbroad and unconstitutional. The Court found the CPPA to be inconsistent with Miller insofar as the CPPA cannot be read to prohibit obscenity, because it lacks the required link between its prohibitions and the affront to community standards prohibited by the obscenity definition.","sumSrc":"Oyez","by":{"0":"33, 40-41, 44-46","2":"7-8, 10, 22"}},{"t":"case","label":"Bachellar v. Maryland","cite":"397 U.S. 564","y":1970,"id":"1969/729","sc":1,"sum":"Petitioners' convictions for violating Maryland's disorderly conduct statute stemming from a demonstration protesting the Vietnam conflict must be set aside, as the jury's general verdict, in light of the trial judge's instructions, could have rested on several grounds, including \"the doing or saying... of that which offends, disturbs, incites, or tends to incite a number of people gathered in the same area,\" and a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Board of Airport Comm’rs v. Jews for Jesus","cite":"482 U.S. 569","y":1987,"id":"1986/86-104","sc":1,"sum":"Using the \"First Amendment overbreadth doctrine,\" which allows an individual to challenge a statute on its face which is potentially threatening to others, the Court found that the ordinance violated the Constitution.","sumSrc":"Oyez","by":{"0":"passim","1":"38, 39, 52","2":"2, 6-9"}},{"t":"case","label":"Boos v. Barry","cite":"485 U.S. 312","y":1988,"id":"1987/86-803","sc":1,"sum":"The Court found that the Code's restriction on sign displays violated the First Amendment while the ban on congregations did not. First, Justice O'Connor argued that the prohibition on signs failed to meet the high standards that the Court uses when evaluating the content-based regulation of political speech in a public forum.","sumSrc":"Oyez","by":{"0":"23, 32"}},{"t":"case","label":"Bose Corp. v. Consumers Union of United States","cite":"466 U.S. 485","y":1984,"id":"1983/82-1246","sc":1,"sum":"The Court held that while the record revealed that the article's author mistakenly described the sound path of Bose speakers, he did not do so with actual malice.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Broadrick v. Oklahoma","cite":"413 U.S. 601","y":1973,"id":"1972/71-1639","sc":1,"sum":"Section 818 of the Oklahoma statute is not unconstitutional on its face. CSC v. Letter Carriers, ante, p. 548.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 29, 41","1":"36, 37, 55","2":"3"}},{"t":"case","label":"Brockett v. Spokane Arcades, Inc.","cite":"472 U.S. 491","y":1985,"id":"1984/84-28","sc":1,"sum":"The Court of Appeals erred in facially invalidating the statute in its entirety.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","1":"58","2":"4"}},{"t":"case","label":"Brown v. Hartlage","cite":"456 U.S. 45","y":1982,"id":"1981/80-1285","sc":1,"sum":"Section 121.055 was applied in this case to limit speech in violation of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33-34"}},{"t":"case","label":"Brown v. Louisiana","cite":"383 U.S. 131","y":1966,"id":"1965/41","sc":1,"sum":"The divided Court found that the actions of the police violated the Constitution. Justice Fortas argued that states may only regulate the use of public facilities in a \"reasonably nondiscriminatory manner, equally applicable to all.\" Maintaining separate library facilities clearly violated this principle.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Buckley v. American Constitutional Law Foundation, Inc.","cite":"525 U.S. 182","y":1999,"id":"1998/97-930","sc":1,"sum":"In a 6-to-3 decision, the Court found the name, badge, and disclosure requirements to be unconstitutional. Weighing Colorado's need to protect the integrity of the initiative-petition process against the burdens that its guidelines placed on political expression, the Court found that the latter outweighed the former.","sumSrc":"Oyez","by":{"0":"3, 20"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"20, 26, 47","1":"38"}},{"t":"case","label":"Burson v. Freeman","cite":"504 U.S. 191","y":1992,"id":"1991/90-1056","sc":1,"ar":11,"sum":"After subjecting Tennessee's statute to exacting scrutiny, since it constituted a facial content-based restriction on political speech in a public forum, the Court held that the statute was narrowly drafted to serve a compelling state interest. By creating a safe zone around polling sites, the statute served the state's interest in protecting its citizen's right to vote freely and effectively.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"6, 17"}},{"t":"case","label":"Christianson v. Colt Industries Operating Corp.","cite":"486 U.S. 800","y":1988,"id":"1987/87-499","sc":1,"sum":"The principal statutes involved in this case, which arises from a jurisdictional dispute between Courts of Appeals, are 28 U. S. C. § 1295(a)(1)granting the Federal Circuit exclusive jurisdiction over an appeal from a final decision of a federal district court \"if the jurisdiction of that court was based, in whole or in part, on\" 28 U. S. C. § 1338-and § 1338(a), which grants the district courts original …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Citizens United v. Federal Election Comm’n","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"0":"20, 30, 40","1":"34, 38","2":"16"}},{"t":"case","label":"City of Chicago v. Morales","cite":"527 U.S. 41","y":1999,"id":"1998/97-1121","sc":1,"sum":"The Court held that Chicago's Gang Congregation Ordinance was unconstitutionally vague and provided law enforcement officials too much discretion to decide what activities constitute loitering.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"City of Houston, Tex. v. Hill","cite":"482 U.S. 451","y":1987,"id":"1986/86-243","sc":1,"sum":"Upon shouting at police in an attempt to divert their attention from his friend during a confrontation, appellee was arrested for \"wilfully... interrupt[ing] a city policeman... by verbal challenge during an investigation\" in violation of a municipal ordinance making it unlawful for any person \"to assault, strike or in any manner oppose, molest, abuse or interrupt any policeman in the execution of his duty.\" After …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42-43, 45","2":"22-23"}},{"t":"case","label":"City of Lakewood v. Plain Dealer Publ’g Co.","cite":"486 U.S. 750","y":1988,"id":"1987/86-1042","sc":1,"sum":"The Court held that the licensing ordinance was facially invalid since it gave Lakewood's mayor unbridled discretion to discriminate against permit seekers, based on the content of their publications and viewpoints. This, in turn, promoted self-censorship by publishers and other speakers who sought to curry favor with the mayor's officer in order to secure the approval of their licensing requests.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Clark v. Cmty. for Creative Non-Violence","cite":"468 U.S. 288","y":1984,"id":"1983/82-1998","sc":1,"sum":"In a 7-to-2 decision, the Court held that the regulations did not violate the First Amendment. The Court noted that expression is subject to reasonable time, place, and manner restrictions, and that the manner of the protest was at odds with the government's interest in maintaining the condition of the parks.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Cohen v. California","cite":"403 U.S. 15","y":1971,"id":"1970/299","sc":1,"ar":1,"sum":"The Court ruled that a California statute prohibiting the display of offensive messages such as \"F--- the Draft\" violated freedom of expression as protected by the First Amendment.","sumSrc":"Oyez","by":{"0":"16, 18, 20-21, 46-47","1":"33","2":"9, 16"}},{"t":"case","label":"Consolidated Edison Co. of N.Y. v. Public Service Comm’n of N.Y.","cite":"447 U.S. 530","y":1980,"id":"1979/79-134","sc":1,"sum":"An order of appellee New York Public Service Commission that prohibits the inclusion by appellant (and other public utility companies) in monthly bills of inserts discussing controversial issues of public policy directly infringes the freedom of speech protected by the First and Fourteenth Amendments and thus is invalid. Cf. First National Bank of Boston v. Bellotti, 435 U. S. 765.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 24"}},{"t":"case","label":"Cornelius v. NAACP Legal Defense & Educ. Fund, Inc.","cite":"473 U.S. 788","y":1985,"id":"1984/84-312","sc":1,"sum":"By Executive Order, participation in the Combined Federal Campaign (CFC), a charity drive aimed at federal employees, is limited to voluntary, tax-exempt, nonprofit charitable agencies that provide direct health und welfare services to individuals or their families, and legal defense and political advocacy organizations are specifically excluded. Participating organizations confine their fundraising activities to a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","1":"passim"}},{"t":"case","label":"Cox v. Louisiana","cite":"379 U.S. 536","y":1965,"id":"1964/24","sc":1,"sum":"The Court determined whether two Louisiana statutes, one prohibiting \"disturbing the peace,\" and the other prohibiting \"obstructing public passages,\" are unconstitutionally vague and thus constitute unconstitutional infringements on the First Amendment rights to free speech and assembly.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Dariano v. Morgan Hill Unified Sch. Dist.","cite":"767 F.3d 764","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/767/764/","sum":"Upholding a prohibition on an American flag shirt at a school.","sumSrc":"brief:0","by":{"0":"27"}},{"t":"case","label":"Davis v. Michigan Dep’t of Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"sum":"Section 111 allows a state to tax income paid by the federal government \"if the taxation does not discriminate against the officer or employee because of the source of the pay or compensation.\" Because the Court found no \"significant differences between the two classes [federal and state employees],\" it held that the Michigan tax distinguished between employees solely on \"the source of the pay.\".","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Erznoznik v. City of Jacksonville","cite":"422 U.S. 205","y":1975,"id":"1974/73-1942","sc":1,"sum":"The Court struck down the Jacksonville ordinance. While individuals did have a right to not be exposed to offensive films, the ordinance singled out \"some kinds of speech on the ground that they are more offensive than others,\" Justice Lewis F. Powell, Jr. wrote for the majority.","sumSrc":"Oyez","by":{"0":"32-33","1":"58","2":"14"}},{"t":"case","label":"Fabri-Tek, Inc. v. NLRB","cite":"352 F.2d 577","y":1965,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/352/577/","by":{"0":"46"}},{"t":"case","label":"FCC v. League of Women Voters of Cal.","cite":"468 U.S. 364","y":1984,"id":"1983/82-912","sc":1,"sum":"Even though the Commerce Clause gives Congress the power to regulate the broadcast medium, \"since broadcasters are engaged in a vital and independent form of communicative activity,\" Congress must use the First Amendment to \"inform and give shape\" to its regulation.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"FCC v. Pacifica Foundation","cite":"438 U.S. 726","y":1978,"id":"1977/77-528","sc":1,"sum":"The Court held that audience, medium, time of day and method of transmission were all relevant factors in determining what speech is protected by the First Amendment.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Federal Election Comm’n v. Massachusetts Citizens for Life","cite":"479 U.S. 238","y":1986,"id":"1986/85-701","sc":1,"sum":"The Court held unanimously that Massachusetts Citizens for Life’s flyers violated FECA’s prohibition on expenditures. He pointed to the general definitions section of FECA, where ‘expenditures’ included the provision of anything of value made for the purpose of influencing a federal election.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Federal Election Comm’n v. Wisconsin Right To Life, Inc.","cite":"551 U.S. 449","y":2007,"id":"2006/06-969","sc":1,"sum":"By a 5-4 vote the Court ruled that BCRA's limitations on political advertising were unconstitutional as they applied to issue ads like WRTL's. Chief Justice John Roberts's majority opinion held that the ads were genuine issue ads, not express political advocacy or its functional equivalent (which Congress can concededly regulate).","sumSrc":"Oyez","by":{"0":"20, 22, 41, 44","1":"38"}},{"t":"case","label":"Forsyth County, Ga. v. Nationalist Movement","cite":"505 U.S. 123","y":1992,"id":"1991/91-538","sc":1,"sum":"The Court held that an ordinance that permits a government administrator to vary the fee for assembling or parading to reflect the estimated cost of maintaining public order violated the free-speech guarantees under the First and Fourteenth Amendments.","sumSrc":"Oyez","by":{"0":"22-23, 36","1":"17, 22"}},{"t":"case","label":"Grayned v. City of Rockford","cite":"408 U.S. 104","y":1972,"id":"1971/70-5106","sc":1,"sum":"1. Antipicketing ordinance, virtually identical with one invalidated as violative of equal protection in Police Department of Chicago v. Mosley, ante, p. 92, is likewise invalid.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","1":"17, 18"}},{"t":"case","label":"Hurley v. Irish–Am. Gay, Lesbian & Bisexual Grp. of Boston","cite":"515 U.S. 557","y":1995,"id":"1994/94-749","sc":1,"sum":"A unanimous court held that the State Court's ruling to require private citizens who organize a parade to include a group expressing a message that the organizers do not wish to convey violates the First Amendment by making private speech subordinate to the public accommodation requirement.","sumSrc":"Oyez","by":{"0":"39-40"}},{"t":"case","label":"Hustler Magazine, Inc. v. Falwell","cite":"485 U.S. 46","y":1988,"id":"1987/86-1278","sc":1,"sum":"The Court ruled that the First Amendment's freedom of speech protection extended to the making of clearly offensive statements about public figures, so long as such speech could not reasonably be construed to convey facts about its subject.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"John Doe No. 1 v. Reed","cite":"561 U.S. 186","y":2010,"id":"2009/09-559","sc":1,"sum":"The Court held that requiring the disclosure of the names of individuals who sign a referendum petition does not violate the signers' First Amendment rights to protection of political speech.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Matal v. Tam","cite":"137 S. Ct. 1744","y":2017,"id":"2016/15-1293","sc":1,"sum":"The Court determined that the Disparagement Clause prohibits trademarks that disparage the members of a racial or ethnic group and violates the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"26","1":"50"}},{"t":"case","label":"McCutcheon v. Federal Election Comm’n","cite":"134 S. Ct. 1434","y":2014,"id":"2013/12-536","sc":1,"sum":"The Court ruled that the two-year aggregate campaign contribution limit of the Bipartisan Campaign Reform Act was unconstitutional.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"McIntyre v. Ohio Elections Comm’n","cite":"514 U.S. 334","y":1995,"id":"1994/93-986","sc":1,"sum":"The freedom to publish anonymously is protected by the First Amendment and \"extends beyond the literary realm to the advocacy of political causes.\" When a law burdens such anonymous speech, the Court applies \"exacting scrutiny,\" upholding the restriction only if it is narrowly tailored to serve an overriding state interest.","sumSrc":"Oyez","by":{"0":"21, 45","2":"8"}},{"t":"case","label":"Members of City Council of City of Los Angeles v. Taxpayers for Vincent","cite":"466 U.S. 789","y":1984,"id":"1983/82-975","sc":1,"sum":"Section 28.04 of the Los Angeles Municipal Code prohibits the posting of signs on public property. Appellee Taxpayers for Vincent, a group of supporters of a candidate for election to the Los Angeles City Council, entered into a contract with appellee Candidates' Outdoor Graphics Service (COGS) to fabricate and post signs with the candidate's name on them. COGS produced cardboard signs and attached them to utility …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","1":"56","2":"7"}},{"t":"case","label":"Mills v. Alabama","cite":"384 U.S. 214","y":1966,"id":"1965/597","sc":1,"sum":"Appellant, a Birmingham, Alabama, newspaper editor, was arrested on a complaint of violating § 285 of the Alabama Corrupt Practices Act by writing And publishing on election day an editorial urging adoption in that election of the mayor-council form of government. Section 285 proscribes electioneering or soliciting votes on election day for or against any proposition or candidate involved in the election. The trial …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11","1":"10, 42","2":"16-17"}},{"t":"case","label":"Minnesota Majority v. Mansky","cite":"62 F. Supp. 3d 870","y":2014,"court":"D. Minn.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/62/870/","by":{"0":"1"}},{"t":"case","label":"Minnesota Majority v. Mansky","cite":"708 F.3d 1051","y":2013,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/708/1051/","by":{"0":"1, 8, 12","1":"24, 31, 24"}},{"t":"case","label":"Minnesota Majority v. Mansky","cite":"789 F. Supp. 2d 1112","y":2011,"court":"D. Minn.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/789/1112/","by":{"0":"1"}},{"t":"case","label":"Minnesota Majority v. Mansky","cite":"849 F.3d 749","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/849/749/","by":{"0":"1"}},{"t":"case","label":"Morse v. Frederick","cite":"551 U.S. 393","y":2007,"id":"2006/06-278","sc":1,"sum":"The Court found an Alaska public school principal had the right to suspend a student for holding up a \"BONG HiTS 4 JESUS\" banner at a school-sponsored event.","sumSrc":"Oyez","by":{"0":"20, 45","1":"28, 50, 52"}},{"t":"case","label":"National Ass’n for Advancement of Colored People v. Button","cite":"371 U.S. 415","y":1963,"id":"1962/5","sc":1,"sum":"Virginia's prosecution of the NAACP was constitutionally proscribed","sumSrc":"Oyez","by":{"0":"14, 22, 41","2":"8"}},{"t":"case","label":"New York Times Co. v. Sullivan","cite":"376 U.S. 254","y":1964,"id":"1963/39","sc":1,"sum":"The Court held that the First Amendment protects freedom of speech and freedom of the press, even about the conduct of politicians, unless the statements are made with actual malice.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"New York v. Ferber","cite":"458 U.S. 747","y":1982,"id":"1981/81-55","sc":1,"sum":"In the Court's first examination of a statute specifically targeted against child pornography, it found that the state's interest in preventing sexual exploitation of minors was a compelling \"government objective of surpassing importance.\" The law was carefully drawn to protect children from the mental, physical, and sexual abuse associated with pornography while not violating the First Amendment.","sumSrc":"Oyez","by":{"0":"22","2":"6"}},{"t":"case","label":"Perry Educ. Ass’n v. Perry Local Educators’ Ass’n","cite":"460 U.S. 37","y":1983,"id":"1982/81-896","sc":1,"sum":"Justice Byron White delivered the opinion of a 5-4 court. The school board chose to grant exclusive access to the official teachers union in order to facilitate a collective-bargaining agreement. It did not act to suppress the speech of rival teachers unions. The school board entrusted PEA with obligations as the sole representative of teachers that would require the use of the mail system.","sumSrc":"Oyez","by":{"0":"18-19","1":"passim"}},{"t":"case","label":"Picray v. Secretary of State","cite":"916 P.2d 324","y":1996,"court":"Or. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/916/324/","by":{"0":"6, 29, 32-33"}},{"t":"case","label":"Police Dep’t of Chicago v. Mosley","cite":"408 U.S. 92","y":1972,"id":"1971/70-87","sc":1,"sum":"The exemption for labor picketing violated the equal protection clause. Government regulation of message content is presumed unconstitutional unless there are compelling justifications. And regulations that selectively exclude speakers from a public forum must undergo careful judicial examination to ensure the minimal degree of furthering an important government interest.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Reed v. Town of Gilbert, Ariz.","cite":"135 S. Ct. 2218","y":2015,"id":"2014/13-502","sc":1,"sum":"The Court decided that extra restrictions placed on signs describing the location of nonprofit events do not survive strict scrutiny and are therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"19-20, 23","1":"34"}},{"t":"case","label":"Regan v. Time, Inc.","cite":"468 U.S. 641","y":1984,"id":"1983/82-729","sc":1,"sum":"The judgment is affirmed in part and reversed in part. 539 F. Supp. 1371, affirmed in part and reversed in part.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Reno v. American Civil Liberties Union","cite":"521 U.S. 844","y":1997,"id":"1996/96-511","sc":1,"sum":"The Court ruled that certain provisions of the Communications Decency Act concerning \"indecent\" behavior were unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"42","2":"8"}},{"t":"case","label":"Republican Party of Minn. v. White","cite":"536 U.S. 765","y":2002,"id":"2001/01-521","sc":1,"sum":"The Court held that the announce clause violates the First Amendment. The Court reasoned that the announce clause prohibits speech based on its content and burdens a category of speech that is at the core of First Amendment freedoms - speech about the qualifications of candidates for public office.","sumSrc":"Oyez","by":{"0":"43, 47"}},{"t":"case","label":"Rosenberger v. Rector and Visitors of University of Virginia","cite":"515 U.S. 819","y":1995,"id":"1994/94-329","sc":1,"sum":"The Court, in a 5-to-4 opinion, held that the University's denial of funding to Rosenberger, due to the content of his message, imposed a financial burden on his speech and amounted to viewpoint discrimination. The Court noted that no matter how scarce University publication funding may be, if it chooses to promote speech at all, it must promote all forms of it equally.","sumSrc":"Oyez","by":{"0":"19","1":"34"}},{"t":"case","label":"Secretary of State of Md. v. Joseph H. Munson Co., Inc.","cite":"467 U.S. 947","y":1984,"id":"1983/82-766","sc":1,"sum":"A Maryland statute prohibits a charitable organization, in connection with any fundraising activity, from paying expenses of more than 25% of the amount raised, but authorizes a waiver of this limitation where it would effectively prevent the organization from raising contributions. Respondent is a professional fundraiser whose Maryland customers include various chapters of the Fraternal Order of Police, at least …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 22, 30, 40","2":"6"}},{"t":"case","label":"Simon & Schuster, Inc. v. Members of N.Y. State Crime Victims Bd.","cite":"502 U.S. 105","y":1991,"id":"1991/90-1059","sc":1,"sum":"The Court concluded that \"New York has singled out speech on a particular subject for a financial burden that it places on no other speech and no other income.\" This discrimination could only be justified if the state could show \"that its regulation is necessary to serve a compelling state interest and is narrowly drawn to achieve that end\" (Arkansas Writers' Project, Inc. v. Ragland, 481 U.S. 221, 231 (1987)).","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Sorrell v. IMS Health Inc.","cite":"564 U.S. 552","y":2011,"id":"2010/10-779","sc":1,"sum":"The Court held that a Vermont statute banning the sale, transmission or use of prescription drug user data violated protected speech of the pharmaceutical research companies, manufacturers and others who use that data.","sumSrc":"Oyez","by":{"0":"19-20","2":"16, 21-22"}},{"t":"case","label":"Texas v. Johnson","cite":"491 U.S. 397","y":1989,"id":"1988/88-155","sc":1,"sum":"The Court held that burning the American Flag is protected free speech under the First Amendment.","sumSrc":"Oyez","by":{"0":"32, 34"}},{"t":"case","label":"Tinker v. Des Moines Independent Community School District","cite":"393 U.S. 503","y":1969,"id":"1968/21","sc":1,"ar":1,"sum":"The Court held that the suspension of students by a public school for wearing black armbands in protest of the Vietnam War violated their First Amendment rights.","sumSrc":"Oyez","by":{"0":"passim","1":"51","2":"13, 15-16"}},{"t":"case","label":"Tobey v. Jones","cite":"706 F.3d 379","y":2013,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/706/379/","by":{"0":"26","2":"9"}},{"t":"case","label":"United States v. Grace","cite":"461 U.S. 171","y":1983,"id":"1982/81-1863","sc":1,"sum":"Section 13k, as applied to the public sidewalks surrounding the Court building, is unconstitutional under the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 14, 30, 32, 46","1":"35, 42","2":"11"}},{"t":"case","label":"United States v. Jones","cite":"18 F.3d 1145","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/18/1145/","by":{"0":"46"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"41, 44","2":"2, 4, 6, 8, 10"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"0":"23","1":"54, 56","2":"9"}},{"t":"case","label":"Van Leer Containers, Inc. v. NLRB","cite":"841 F.2d 779","y":1988,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/841/779/","by":{"0":"45"}},{"t":"case","label":"Vanasco v. Schwartz","cite":"401 F. Supp. 87","y":1975,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./401/87/","by":{"0":"34"}},{"t":"case","label":"Virginia v. Black","cite":"538 U.S. 343","y":2003,"id":"2002/01-1107","sc":1,"sum":"The Court held that a law banning cross-burning with the intent to intimidate is constitutional. However, cross burning is not prima facie evidence of intent to intimidate.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Virginia v. Hicks","cite":"539 U.S. 113","y":2003,"id":"2002/02-371","sc":1,"sum":"The Court held that the RRHA's trespass policy is not facially invalid under the First Amendment's overbreadth doctrine.","sumSrc":"Oyez","by":{"0":"21-22, 29","1":"58","2":"7"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. NLRB","cite":"400 F.3d 1093","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/400/1093/","by":{"0":"45"}},{"t":"case","label":"Washington State Grange v. Washington State Republican Party","cite":"552 U.S. 442","y":2008,"id":"2007/06-713","sc":1,"sum":"The Court reversed the Ninth Circuit's ruling and held the party affiliation provision constitutional. Writing for the majority, Justice Clarence Thomas explained that the state law never referred to the candidates as nominees of any particular party.","sumSrc":"Oyez","by":{"0":"22, 38","2":"7"}},{"t":"case","label":"Washington v. Glucksberg","cite":"521 U.S. 702","y":1997,"id":"1996/96-110","sc":1,"sum":"The Court decided that a law banning physician-assisted suicide does not violate the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"passim","1":"passim"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"case","label":"Opposition to Petition for Writ of Certiorari, Minnesota Majority v. Mansky","cite":"2013 WL 6021145","y":2013,"court":"U.S. Nov. 8","by":{"0":"13"}},{"t":"case","label":"Petition for Writ of Certiorari, Minnesota Majority v. Mansky","cite":"2013 WL 4027040","y":2013,"court":"U.S. Aug. 5","by":{"0":"13"}},{"t":"case","label":"Abrahamson v. St. Louis Cty. Sch. Dist.","cite":"819 N.W.2d 129","y":2012,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W.2d/819/129/","by":{"1":"20"}},{"t":"case","label":"Adderley v. Florida","cite":"385 U.S. 39","y":1966,"id":"1966/19","sc":1,"sum":"The Court found that there were no constitutional violations in this case. The language of the Florida statute was clearly defined and applied, argued Justice Black, which prevented it from imposing broad infringements on speech and expression rights.","sumSrc":"Oyez","by":{"1":"32, 34"}},{"t":"case","label":"Arizonans for Official English v. Arizona","cite":"520 U.S. 43","y":1997,"id":"1996/95-974","sc":1,"sum":"Announced by Justice Ruth Bader Ginsburg, the Court held that the dispute was moot due to the previous resignation of Yniguez. The Court did not rule on the constitutionality of the article.","sumSrc":"Oyez","by":{"1":"57, 58"}},{"t":"case","label":"Bellotti v. Baird","cite":"428 U.S. 132","y":1976,"id":"1975/75-73","sc":1,"sum":"The Court held that the District Court should have abstained and vacated the judgment. There was ambiguity in whether the Massachusetts statute created a \"parental veto,\" which under Planned Parenthood v. Danforth affected the constitutionality of the statute.","sumSrc":"Oyez","by":{"1":"57"}},{"t":"case","label":"Berner v. Delahanty","cite":"129 F.3d 20","y":1997,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/129/20/","sum":"Upholding prohibition on attorneys’ political buttons in courtroom which “can reasonably be thought to compromise the environment of impartiality and fairness”.","sumSrc":"brief:1","by":{"1":"35"}},{"t":"case","label":"Bryant v. Gates","cite":"532 F.3d 888","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/532/888/","by":{"1":"38"}},{"t":"case","label":"Burdick v. Takushi","cite":"504 U.S. 428","y":1992,"id":"1991/91-535","sc":1,"sum":"Hawaii's prohibition on write-in voting does not unreasonably infringe upon its citizens' rights under the First and Fourteenth Amendments.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Christian Legal Soc’y v. Martinez","cite":"561 U.S. 661","y":2010,"id":"2009/08-1371","sc":1,"sum":"The Court held that a college's mandate requiring all officially-recognized student organizations be inclusive and welcoming to all students did not violate a group of Christian students' First Amendment rights when the college refused to recognize a student group that required all members to sign a statement of Christian beliefs for membership.","sumSrc":"Oyez","by":{"1":"32, 36, 45"}},{"t":"case","label":"Citizens for Police Accountability Political Comm. v. Browning","cite":"572 F.3d 1213","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/572/1213/","by":{"1":"45"}},{"t":"case","label":"Cox v. Louisiana","cite":"379 U.S. 559","y":1965,"id":"1964/49","sc":1,"sum":"The Court determined whether a conviction based on a Louisiana statute prohibiting picketing before a courthouse violated the defendant's rights to free speech and assembly under the First and Fourteenth Amendments.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Greer v. Spock","cite":"424 U.S. 828","y":1976,"id":"1975/74-848","sc":1,"ar":2,"sum":"Fort Dix, a federal military reservation devoted primarily to basic training for newly inducted Army personnel, and over which the Government exercises exclusive jurisdiction, permits free civilian access to certain unrestricted areas. However, post regulations ban speeches and demonstrations of a partisan political nature and also prohibit the distribution of literature without prior approval of post headquarters. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"passim"}},{"t":"case","label":"Griffin v. Secretary of Veterans Affairs","cite":"288 F.3d 1309","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/288/1309/","by":{"1":"54"}},{"t":"case","label":"Hodge v. Talkin","cite":"799 F.3d 1145","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/799/1145/","sum":"Upholding prohibition on protesting on the Supreme Court’s plaza.","sumSrc":"brief:1","by":{"1":"passim","2":"12"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"1":"54"}},{"t":"case","label":"Illinois Bd. of Elections v. Socialist Workers Party","cite":"440 U.S. 173","y":1979,"id":"1978/77-1248","sc":1,"sum":"Under the Illinois Election Code, new political parties and independent candidates must obtain the signatures of 25,000 qualified voters in order to appear on the ballot in statewide elections. However, the minimum number of signatures required in elections for offices of political subdivisions of the State is 5% of the number of persons who voted at the previous election for such offices. Application of these …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"International Soc. for Krishna Consciousness, Inc. v. Lee","cite":"505 U.S. 672","y":1992,"id":"1991/91-155","sc":1,"sum":"In a related case, the Court held invalid the airport authority's ban on literature distribution in airport terminals.","sumSrc":"Oyez","by":{"1":"30, 32, 40, 45, 47"}},{"t":"case","label":"Leavitt v. Jane L.","cite":"518 U.S. 137","y":1996,"id":"1995/95-1242","sc":1,"sum":"The anonymous Per Curiam opinion held that the Utah Legislature had explicitly stated that each of the two abortion provisions was meant to stand independent of the other. The Court called the Tenth Circuit's interpretation of the Utah legislature's intent \"questionable when considered in isolation\" and \"plainly error\" when considered in light of the statutory text.","sumSrc":"Oyez","by":{"1":"57"}},{"t":"case","label":"Lehman v. City of Shaker Heights","cite":"418 U.S. 298","y":1974,"id":"1973/73-328","sc":1,"sum":"The Court affirmed the Supreme Court of Ohio and found no violation of the First or Fourteenth Amendments.","sumSrc":"Oyez","by":{"1":"passim"}},{"t":"case","label":"Loughrin v. United States","cite":"134 S. Ct. 2384","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Marlin v. District of Columbia Bd. of Elections & Ethics","cite":"236 F.3d 716","y":2001,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/236/716/","sum":"Recognizing the District of Columbia’s interest in “protecting the orderly conduct of elections by creating a neutral zone within the polling place” and “preventing altercations over hot-button issues”.","sumSrc":"brief:1","by":{"1":"30, 31, 41, 43"}},{"t":"case","label":"McConnell v. FEC","cite":"540 U.S. 93","y":2003,"id":"2003/02-1674","sc":1,"sum":"The Court found that regulations in the Campaign Finance Reform Act of 2002 did not violate the First Amendment.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Minnesota Majority v. Mansky","cite":"134 S. Ct. 824","y":2013,"url":"https://www.courtlistener.com/c/S.%20Ct./134/824/","sc":1,"by":{"1":"11"}},{"t":"case","label":"Minnesota Voters All. v. Anoka-Hennepin Sch. Dist.","cite":"868 N.W.2d 703","y":2015,"court":"Minn. Ct. App.","url":"https://www.courtlistener.com/c/N.W.2d/868/703/","by":{"1":"20"}},{"t":"case","label":"National Endowment for the Arts v. Finley","cite":"524 U.S. 569","y":1998,"id":"1997/97-371","sc":1,"sum":"In an 8-to-1 opinion the Court held that, unlike direct sovereign regulation of speech, Congress enjoys wide latitude when setting spending priorities which may indirectly affect certain forms of expression. The funding of one activity believed to be in the public interest, to the exclusion of another, does not constitute viewpoint discrimination.","sumSrc":"Oyez","by":{"1":"53, 54"}},{"t":"case","label":"New York State Club Ass’n, Inc. v. City of New York","cite":"487 U.S. 1","y":1988,"id":"1987/86-1836","sc":1,"sum":"The Court examined the clubs subjected to anti-discrimination laws closely and found \"no evidence of any club, let alone a substantial number of clubs, for whom the Law impairs the ability to associate or to advocate public or private viewpoints.\" In addition, many of the clubs showed characteristics of a public nature. Often strangers attended club functions, partook in meals, and made financial contributions.","sumSrc":"Oyez","by":{"1":"56"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"PG Publ’g Co. v. Aichele","cite":"705 F.3d 91","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/705/91/","by":{"1":"31"}},{"t":"case","label":"Powerex Corp. v. Reliant Energy Servs., Inc.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"sum":"The Court ruled 7-2 that the Ninth Circuit lacked jurisdiction to review the District Court's remand order. The Court relied on 28 U.S.C. 1447(d), which precludes appellate review of remands based on lack of subject-matter jurisdiction.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Reynolds v. Sims","cite":"377 U.S. 533","y":1964,"id":"1963/23","sc":1,"sum":"The Court held that Alabama's apportionment of the state legislature was unconstitutional under the Equal Protection Clause of the Fourteenth Amendment because representation was not based on population of counties.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Schirmer v. Edwards","cite":"2 F.3d 117","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/2/117/","by":{"1":"45"}},{"t":"case","label":"Schmitt v. McLaughlin","cite":"275 N.W.2d 587","y":1979,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W.2d/275/587/","by":{"1":"20, 21"}},{"t":"case","label":"Smiley v. Holm","cite":"285 U.S. 355","y":1932,"id":"scdb/1931-045","sc":1,"sum":"1. The function of a state legislature in prescribing the time, place and manner of holding elections for Representatives in Congress under Constitution, Art. 1, § 4, is a law-making function in which the veto power of the state governor participates if, under the state constitution, the governor has that power in the making of state laws.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30, 42, 48"}},{"t":"case","label":"Storer v. Brown","cite":"415 U.S. 724","y":1974,"id":"1973/72-812","sc":1,"sum":"Section 6830 (d) (Supp. 1974) of the California Elections Code forbids ballot position to hn independent candidate for-elective public office if he had a registered affiliation with a qualified political party within one year prior to the immediately preceding primary election; § 3831 (1961) requires an independent candidate's nominating papers to be signed by voters not less in number than 5% nor more than 6% of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Tashjian v. Republican Party of Connecticut","cite":"479 U.S. 208","y":1986,"id":"1986/85-766","sc":1,"sum":"A Connecticut statute (§ 9-431), enacted in 1955, requires voters in any political party primary to be registered members of that party. In 1984, appellee Republican Party of Connecticut (Party) adopted a Party rule that permits independent voters -registered voters not affiliated with any party-to vote in Republican primaries for federal and statewide offices. The Party and the Party's federal officeholders and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"United Food & Commercial Workers Local 1099 v. City of Sidney","cite":"364 F.3d 738","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/364/738/","by":{"1":"31"}},{"t":"case","label":"United Sav. Ass’n of Texas v. Timbers of Inwood Forest Assocs., Ltd.","cite":"484 U.S. 365","y":1988,"id":"1987/86-1602","sc":1,"sum":"Undersecured creditors are not entitled to compensation under § 362(d)(1) for the delay caused by the automatic stay in foreclosing on their collateral.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"United States v. Kokinda","cite":"497 U.S. 720","y":1990,"id":"1989/88-2031","sc":1,"sum":"In a divided opinion, the Court ruled that the prohibition was not unconstitutional. Justice Sandra Day O'Connor, writing for a four-member plurality, wrote that the sidewalk was not a public forum. \"Regulation of speech activity on governmental property that has been traditionally open to the public for expressive activity, such as public streets and parks, is examined under strict scrutiny. .","sumSrc":"Oyez","by":{"1":"passim"}},{"t":"case","label":"United States v. O’Brien","cite":"391 U.S. 367","y":1968,"id":"1967/232","sc":1,"sum":"The Court found that it was not an infringement on one's First Amendment rights to criminalize burning a draft card.","sumSrc":"Oyez","by":{"1":"52","2":"21"}},{"t":"case","label":"United States Civil Serv. Comm’n v. National Ass’n of Letter Carriers","cite":"413 U.S. 548","y":1973,"id":"1972/72-634","sc":1,"sum":"Some individual federal employees, an employees' union, and certain local Democratic and Republican political committees filed this action challenging as unconstitutional on its face the prohibition in § 9 (a) of the Hatch Act, 5 U. S. C. § 7324 (a) (2), against federal employees' taking \"an active part in political management or in political campaigns.\" The section defines the phrase as \"those acts of political …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37, 55"}},{"t":"case","label":"xv USPS v. Council of Greenburgh Civic Ass’ns","cite":"453 U.S. 114","y":1981,"id":"1980/80-608","sc":1,"sum":"Section 1725 does not unconstitutionally abridge appellees' First Amendment rights, inasmuch as neither the enactment nor the enforcement of § 1725 is geared in any way to the content of the message sought to be placed in the letterbox.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32, 54"}},{"t":"case","label":"Virginia v. American Booksellers Ass’n, Inc.","cite":"484 U.S. 383","y":1988,"id":"1987/86-1034","sc":1,"sum":"A 1985 amendment to a Virginia statute makes it unlawful for any person \"to knowingly display for commercial purposes in a manner whereby juveniles may examine and peruse\" certain visual or written sexual or sadomasochistic material that is harmful to juveniles. What is \"harmful to juveniles\" is defined elsewhere in the statute. Plaintiffs, a number of booksellers' organizations and two Virginia non-\"adults only,\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"57, 58"}},{"t":"case","label":"Ward v. Rock Against Racism","cite":"491 U.S. 781","y":1989,"id":"1988/88-226","sc":1,"sum":"The Court upheld the ordinance, giving broad deference to the government's interest in maintaining order. As long as \"the means chosen are not substantially broader than necessary to achieve the government's interest,\" a regulation will not be invalidated because a court concludes that the government's interest \"could be adequately served by some less-speech-restrictive alternative.\".","sumSrc":"Oyez","by":{"1":"17, 55"}},{"t":"case","label":"Wesberry v. Sanders","cite":"376 U.S. 1","y":1964,"id":"1963/22","sc":1,"sum":"The Court ruled that Georgia's apportionment system, which allowed for uneven distribution of voters among different congressional districts, violated the Fourteenth Amendment by depriving citizens the full benefit of their right to vote.","sumSrc":"Oyez","by":{"1":"1, 41"}},{"t":"case","label":"Williams-Yulee v. Florida Bar","cite":"135 S. Ct. 1656","y":2015,"id":"2014/13-1499","sc":1,"sum":"The Court held that a rule prohibiting judicial candidates from personally soliciting campaign funds does not violate the First Amendment.","sumSrc":"Oyez","by":{"1":"48, 49, 50"}},{"t":"const","label":"Article I, Section 4, Clause 1","clauses":[["elections-clause","Elections Clause"]],"text":"The Times, Places and Manner of holding Elections for Senators and Representatives, shall be prescribed in each State by the Legislature thereof; but the Congress may at any time by Law make or alter such Regulations, except as to the Places of chusing Senators.","by":{"1":"42"}},{"t":"case","label":"Baggett v. Bullitt","cite":"377 U.S. 360","y":1964,"id":"1963/220","sc":1,"sum":"This class action was brought by members of the faculty, staff, and students of the University of Washington for a judgment declaring unconstitutional 1931 and 1955 state statutes requiring the taking of oaths, one for teachers and the other for all state employees, including teachers, as a condition of employment. The 1931 oath requires teachers to swear, by precept and example, to promote respect for the flag and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5, 9"}},{"t":"case","label":"Bd. of Regents v. Southworth","cite":"529 U.S. 217","y":2000,"id":"1999/98-1189","sc":1,"sum":"The Court held that the \"First Amendment permits a public university to charge its students an activity fee used to fund a program to facilitate extracurricular student speech if the program is viewpoint neutral.\" Justice Kennedy wrote for the Court that, \"[w]hen a university requires its students to pay fees to support the extracurricular speech of other students, all in the interest of open discussion, it may not prefer some viewpoints to others.\" Justice David H. Souter, in an opinion joined by Justices John Paul Stevens and Stephen G. Breyer, concurred in the judgment only.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Bell v. Wolfish","cite":"441 U.S. 520","y":1979,"id":"1978/77-1829","sc":1,"sum":"The Court found that that the conditions of confinement did not infringe upon a pretrial detainee's rights. Justice Rehnquist's opinion argued that the issue of prison management is ripe with \"judgment calls\" which rest outside the jurisdiction of the judiciary.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Brown v. Entm’t Merchants Ass’n","cite":"564 U.S. 786","y":2011,"id":"2010/08-1448","sc":1,"sum":"The Court held that video games, including violent ones, are protected speech under the First Amendment.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"City of Cincinnati v. Discovery Network, Inc.","cite":"507 U.S. 410","y":1993,"id":"1992/91-1200","sc":1,"sum":"The city's selective and categorical ban on the distribution, via newsrack, of \"commercial handbills\" is not consistent with the dictates of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21-22"}},{"t":"case","label":"Dombrowski v. Pfister","cite":"380 U.S. 479","y":1965,"id":"1964/52","sc":1,"sum":"Appellants, a civil rights organization and its executive director, brought suit in Federal District Court, in which other individuals later joined, for injunctive and declaratory relief to restrain appellees from prosecuting or threatening to prosecute them under Louisiana's Subversive Activities and Communist Control Law and Communist Propaganda Control Law, which they alleged violated their rights of free …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Eagle Point Educ. Ass’n/SOBC/OEA v. Jackson County School Dist. No. 9","cite":"2018 WL 560527","y":2018,"court":"9th Cir. Jan. 26","by":{"2":"14-15"}},{"t":"case","label":"Harman v. Forssenius","cite":"380 U.S. 528","y":1965,"id":"1964/360","sc":1,"sum":"In anticipation of the promulgation of the Twenty-fourth Amendment abolishing the poll tax as a requirement for voting in federal elections, Virginia eliminated the poll tax as an absolute prerequisite to voting in federal elections and in its stead substituted a provision whereby the federal voter could qualify either by paying the customary poll tax or by filing a certificate of residence six months before the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"Lewis v. City of New Orleans","cite":"415 U.S. 130","y":1974,"id":"1973/72-6156","sc":1,"sum":"The ordinance, as thus construed, is susceptible of application to protected speech, and therefore is overbroad in violation of the First and Fourteenth Amendments and facially invalid. The ordinance plainly has a broader sweep than the constitutional definition of \"fighting words\" as being words \"which by their very utterance inflict injury or tend to incite an immediate breach of the peace,\" Chaplinsky v. New …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8, 10"}},{"t":"case","label":"Mayor of Philadelphia v. Educ. Equality League","cite":"415 U.S. 605","y":1974,"id":"1973/72-1264","sc":1,"sum":"The Mayor of Philadelphia is empowered by the city charter to appoint a Nominating Panel, which in turn submits to him nominees to fill vacancies on the School Board. The Panel consists of 13 members. The Mayor must appoint four members from the citizenry at large; each of the remaining nine must be the highest ranking officer of one of nine designated categories of citywide organizations. A new Panel is convened in …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"Monitor Patriot Co. v. Roy","cite":"401 U.S. 265","y":1971,"id":"1970/62","sc":1,"sum":"1.. Publications concerning candidates for public office must be accorded at least as much protection under the First and Fourteenth Amendments as those concerning occupants of public office.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Nevada Comm’n on Ethics v. Carrigan","cite":"564 U.S. 117","y":2011,"id":"2010/10-568","sc":1,"sum":"The Court held that the Nevada law requiring elected officials to disqualify themselves when they are asked to vote on matters that present a conflict of interest was constitutional.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Nixon v. Shrink Mo. Gov’t PAC","cite":"528 U.S. 377","y":2000,"id":"1999/98-963","sc":1,"sum":"The Court held that Buckley is the authority for comparable state regulation and, but that the federal limits approved in Buckley, with or without adjustment for inflation, do not define the scope of permissible state limitations.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Packingham v. North Carolina","cite":"137 S. Ct. 1730","y":2017,"id":"2016/15-1194","sc":1,"sum":"The Court determined that the North Carolina law prohibiting registered sex offenders from accessing various websites, where minors are known to be active and have accounts, regardless of whether or not the sex offender directly interacted with a minor violates the First Amendment.","sumSrc":"Oyez","by":{"2":"10, 17"}},{"t":"case","label":"Schad v. Borough of Mount Ephraim","cite":"452 U.S. 61","y":1981,"id":"1980/79-1640","sc":1,"sum":"Appellants' convictions are invalid under the First and Fourteenth Amendments for appellee failed to justify the exclusion of live entertainment from the broad range of commercial uses permitted in the borough.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"11"}},{"t":"case","label":"Smith v. Daily Mail Publ’g Co.","cite":"443 U.S. 97","y":1979,"id":"1978/78-482","sc":1,"sum":"Chief Justice Burger reasoned that governmental attempts to restrict the publication of truthful information \"seldom can satisfy constitutional standards.\" As long as the information is lawfully obtained, as it was in this case involving a shooting at a junior high school, the state cannot restrict a newspaper from publishing a juvenile offender's name unless the restriction serves a substantial state interest.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Spence v. Wash.","cite":"418 U.S. 405","y":1974,"id":"1973/72-1690","sc":1,"sum":"The Supreme Court held that that statute, as applied, violated the First Amendment right to free speech. Justice William O. Douglas concurred, writing that Spence’s display was symbolic speech entitled to constitutional protection. Justice Harry A. Blackmun concurred in the result.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Stromberg v. California","cite":"283 U.S. 359","y":1931,"id":"1900-1940/283us359","sc":1,"sum":"A case in which the Court struck down under the First Amendment a portion of a California law prohibiting the display of a red flag in a public place \"as a sign, symbol, or emblem of opposition to organized government.\"","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Talley v. California","cite":"362 U.S. 60","y":1960,"id":"1959/154","sc":1,"sum":"The ordinance is void on its face, and the conviction is reversed. Lovell v. Griffin. 303 U. S. 444. Pp. 60-66. 172 Cal. App. 2d Supp. 797, 332 P. 2d 447, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"Thornhill v. Alabama","cite":"310 U.S. 88","y":1940,"id":"1940-1955/310us88","sc":1,"sum":"In an 8-to-1 decision, the Court held that Section 3448 of the Alabama State Code was facially invalid.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"United States v. CIO","cite":"335 U.S. 106","y":1948,"id":"scdb/1947-113","sc":1,"sum":"A labor organization and its president were indicted for violations of § 313 of the Corrupt Practices Act of 1925, as amended by § 304 of the Labor Management Relations Act of 1947, which prohibits contributions or expenditures by corporations and labor organizations in connection with federal elections. The indictment charged that the labor organization made, and its president consented to, expenditures for the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17, 19"}},{"t":"case","label":"United States v. National Treasury Employees Union","cite":"513 U.S. 454","y":1995,"id":"1994/93-1170","sc":1,"sum":"In a 6 to 3 decision delivered by Justice John Paul Stevens, the Court declared that a flat ban violated free-speech rights. Concerns about impropriety do not apply if there is no link between a government employee's job and \"the subject matter of the expression or the character of the payor.\".","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Van Orden v. Perry","cite":"545 U.S. 677","y":2005,"id":"2004/03-1500","sc":1,"sum":"The Court held that a Ten Commandments monument erected on the state capitol building's grounds did not violate the establishment clause of the First Amendment.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Village of Hoffman Estates v. Flipside, Hoffman Estates, Inc.","cite":"455 U.S. 489","y":1982,"id":"1981/80-1681","sc":1,"sum":"The ordinance is not facially overbroad or vague but is reasonably clear in its application to appellee.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9-10"}},{"t":"case","label":"Wooley v. Maynard","cite":"430 U.S. 705","y":1977,"id":"1976/75-1453","sc":1,"sum":"In a 6-to-3 decision, the Court held that New Hampshire could not constitutionally require citizens to display the state motto upon their vehicle license plates.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Zwickler v. Koota","cite":"389 U.S. 241","y":1967,"id":"1967/29","sc":1,"sum":"Reversal on state law grounds of appellant's conviction of violating a New York statute by distributing anonymous political handbills was affirmed by the State's highest court. Thereafter appellant, invoking federal jurisdiction under the Civil Rights Act and the Declaratory Judgment Act, sought in the District Court declaratory relief and an injunction against future criminal prosecutions for violating the statute, …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"usc","label":"28 U.S.C. § 2106","url":"https://www.law.cornell.edu/uscode/text/28/2106","by":{"2":"24"}}]};